Tool: find_brewed_batches_with_yeast_and_gravity
Description: Find Brewed Batches With Yeast And Gravity
Parameters:
    {
      "type": "object",
      "properties": {
        "yeast_strain_name": {
          "type": "string",
          "description": "Name of the yeast strain to filter by",
          "title": "Yeast Strain Name"
        },
        "min_final_gravity": {
          "type": "number",
          "description": "Minimum final gravity threshold",
          "title": "Min Final Gravity"
        },
        "months_back": {
          "type": "integer",
          "description": "Number of months back to look for batches",
          "title": "Months Back"
        }
      },
      "required": [
        "yeast_strain_name",
        "min_final_gravity",
        "months_back"
      ]
    }

